// "Run options": adds the client (without its dataset list) to the run, so every later step knows
// whose name, style and feeds to use. Set test_tamper to true to change one number in the script
// and watch the guard stop the run.
const { data_sources, ...client } = $("Client").first().json;
return [{ json: { ...$input.first().json, client, started_at: new Date().toISOString(), test_tamper: false } }];

// "Add trace link": keeps the run and adds the links to its trace pages, if the render service saved
// them. A failed save leaves the links empty; the run goes on.
const run = $("Numbers check out?").first().json;
const r = $input.first().json;
return [{ json: { ...run, trace_id: r.trace_id ?? null, trace_url: r.trace_url ?? null, story_page_url: r.story_url ?? null } }];

// "Why it stopped": one line for the editor (must-work row 10).
const j = $input.first().json;
const reason = j.reason || j.error?.message || j.message || "A step failed without saying why.";
return [{ json: { text: `No story today. ${reason}` } }];
